    ExchangeFulfillment fulfillment(){ExchangeFulfillment f=new ExchangeFulfillment();ReflectionTestUtils.setField(f,"repository",repo);ReflectionTestUtils.setField(f,"exchanges",service);ReflectionTestUtils.setField(f,"catalog",catalog);OrderStockClient stock=mock(OrderStockClient.class);ReflectionTestUtils.setField(f,"inventory",stock);when(stock.execute(anyString(),anyString(),any(),anyString())).thenAnswer(a->{com.oms.common.model.dto.OrderStockCommand c=a.getArgument(2);return R.ok(Collections.singletonList(map("platform_oid",c.getLines().get(0).getPlatformOid(),"sku_sn",c.getLines().get(0).getSkuSn(),"reserved_quantity",c.getLines().get(0).getQuantity())));});return f;}
    @Test void replacementHasIndependentDemandUnderOriginalSoWithoutCreatingAnotherOrder(){long id=ingest(source());service.review("VERIFY",id,review(id),"test");ExchangeFulfillment f=fulfillment();assertTrue(f.reserve("VERIFY",id));assertEquals(order,f.materialize("VERIFY",id));assertEquals(order,f.materialize("VERIFY",id));assertEquals(1L,db.queryForObject("SELECT COUNT(*) FROM oms_order",Long.class));assertEquals(1L,db.queryForObject("SELECT COUNT(*) FROM oms_platform_order",Long.class));Map<String,Object> replacement=db.query("SELECT * FROM oms_order_line WHERE exchange_id=?",ROW,id).get(0);assertEquals("EXCHANGE:"+id,replacement.get("stock_reference"));assertEquals("EXCHANGE",replacement.get("business_type"));assertEquals(line,number(replacement,"source_line_id"));assertEquals(original,repo.raw("VERIFY",platform).get("raw_payload"));assertEquals(25,new java.math.BigDecimal(text(db.query("SELECT payment FROM oms_order WHERE id=?",ROW,order).get(0),"payment")).intValue());}
    long shippedReplacement(long exchange){Map<String,Object> e=service.row("VERIFY",exchange,false);long parent=number(e,"fulfillment_line_id");long sh=repo.insert("INSERT INTO oms_order_shipment(company_code,shipment_sn,order_id,order_sn,channel_id,platform_tid,generation_no,owner_code,real_store_code,real_store_name,quantity,created_by,business_type,exchange_id,stock_reference) VALUES ('VERIFY',?,?,'SO_EXCHANGE',1,'987654321012345678',?,'O','W','warehouse',2,'test','EXCHANGE',?,?)","XS_REPLACE_"+exchange,order,exchange+2,exchange,"EXCHANGE:"+exchange);return repo.insert("INSERT INTO oms_order_shipment_line(company_code,shipment_id,allocation_id,order_line_id,platform_oid,sku_sn,goods_name,store_code,batch_id,source_type,stock_source_id,quantity,shipped_quantity) VALUES ('VERIFY',?,?,?,'987654321012345679',?,'replacement','V1',1,'PUBLIC_EXTRA',1,2,2)",sh,10000+exchange,parent,e.get("target_sku"));}
    @Test void aToBThenBToAUsesDistinctShipmentSourcesAndCannotReuseConsumedEntitlement(){
        when(catalog.goods(anyString(),anyList())).thenReturn(mapGoods());long first=ingest(source());service.review("VERIFY",first,review(first),"test");ExchangeFulfillment f=fulfillment();f.reserve("VERIFY",first);f.materialize("VERIFY",first);long bSource=shippedReplacement(first);
        Map<String,Object> next=source();next.put("dispute_id","123457");long second=ingest(next);Map<String,Object> input=review(second);input.put("target_sku","A");input.put("source_shipment_line_id",bSource);service.review("VERIFY",second,input,"test");f.reserve("VERIFY",second);f.materialize("VERIFY",second);long aSource=shippedReplacement(second);Map<String,Object> newA=db.query("SELECT * FROM oms_order_line WHERE exchange_id=?",ROW,second).get(0);assertEquals("A",newA.get("sku_sn"));assertNotEquals(line,number(newA,"id"));assertEquals(number(service.row("VERIFY",first,false),"fulfillment_line_id"),number(newA,"source_line_id"));assertEquals(bSource,number(newA,"source_shipment_line_id"));
        next.put("dispute_id","123458");long third=ingest(next);input=review(third);input.put("source_shipment_line_id",aSource);service.review("VERIFY",third,input,"test");
        next.put("dispute_id","123459");long duplicate=ingest(next);Map<String,Object> again=review(duplicate);again.put("source_shipment_line_id",bSource);assertThrows(IllegalArgumentException.class,()->service.review("VERIFY",duplicate,again,"test"));assertEquals(1L,db.queryForObject("SELECT COUNT(*) FROM oms_order",Long.class));
    }
    Map<String,List<Map<String,Object>>> mapGoods(){Map<String,List<Map<String,Object>>> out=new HashMap<>();for(String sku:Arrays.asList("A","B"))out.put(sku,Collections.singletonList(map("sku_sn",sku,"goods_name",sku)));return out;}
