    @Test void unknownPlatformWriteIsQueriedWithoutSubmittingAgain(){long id=ingest(source());service.review("VERIFY",id,review(id),"test");ExchangeFulfillment f=mock(ExchangeFulfillment.class);when(f.reserve(anyString(),anyLong())).thenReturn(true);ExchangeExecution x=executor(f);java.util.concurrent.atomic.AtomicInteger writes=new java.util.concurrent.atomic.AtomicInteger();when(bridge.call(anyString(),anyLong(),anyMap(),anyString())).thenAnswer(a->{Map<String,Object> request=a.getArgument(2);if("AGREE".equals(request.get("operation"))){writes.incrementAndGet();return R.ok(map("outcome","UNKNOWN","error_code","TIMEOUT"));}return R.ok(map("exchange",source()));});requestAgree(x,id);x.process("VERIFY",id);x.process("VERIFY",id);assertEquals(1,writes.get());assertEquals("UNKNOWN",service.row("VERIFY",id,false).get("platform_operation"));}
    @Test void acknowledgedWriteFollowedByFailedQueryMustRemainUnknown(){long id=ingest(source());service.review("VERIFY",id,review(id),"test");ExchangeFulfillment f=mock(ExchangeFulfillment.class);when(f.reserve(anyString(),anyLong())).thenReturn(true);ExchangeExecution x=executor(f);java.util.concurrent.atomic.AtomicInteger writes=new java.util.concurrent.atomic.AtomicInteger(),queries=new java.util.concurrent.atomic.AtomicInteger();when(bridge.call(anyString(),anyLong(),anyMap(),anyString())).thenAnswer(a->{Map<String,Object> request=a.getArgument(2);if("AGREE".equals(request.get("operation"))){writes.incrementAndGet();return R.ok(map("exchange",source()));}if(queries.incrementAndGet()==1)return R.ok(map("exchange",source()));return R.ok(map("outcome","FAILED","error_code","NO_PERMISSION"));});requestAgree(x,id);x.process("VERIFY",id);assertEquals("UNKNOWN",service.row("VERIFY",id,false).get("platform_operation"));assertEquals(1,writes.get());}
    @Test void insufficientReplacementStockNeverSendsPlatformAgreement(){long id=ingest(source());service.review("VERIFY",id,review(id),"test");ExchangeFulfillment f=mock(ExchangeFulfillment.class);when(f.reserve(anyString(),anyLong())).thenReturn(false);ExchangeExecution x=executor(f);when(bridge.call(anyString(),anyLong(),anyMap(),anyString())).thenReturn(R.ok(map("exchange",source())));requestAgree(x,id);x.process("VERIFY",id);assertEquals("STOCK_WAIT",service.row("VERIFY",id,false).get("platform_operation"));verify(bridge,times(1)).call(anyString(),anyLong(),anyMap(),anyString());}
