    @Test void continueSubmissionOnlyRecordsReviewAndReusesReturnFacts(){long id=stoppedExchange(0);String old= text(service.row("VERIFY",id,false),"stock_request");continuation.submit("VERIFY",id,continueInput(id),"requester");assertEquals("CONTINUE_REVIEW",service.row("VERIFY",id,false).get("control_state"));assertEquals("CLOSED",service.row("VERIFY",id,false).get("state"));assertEquals(old,service.row("VERIFY",id,false).get("stock_request"));assertEquals(2L,db.queryForObject("SELECT COUNT(*) FROM oms_exchange_round WHERE exchange_id=?",Long.class,id));assertEquals("REVIEW",db.queryForObject("SELECT state FROM oms_exchange_round WHERE exchange_id=? AND round_no=2",String.class,id));verify(continuationStock,never()).execute(anyString(),anyString(),any(),anyString());verify(continuationReturns,never()).prepare(anyString(),anyLong(),anyMap(),anyString());verifyNoInteractions(bridge);}
