    @Test void partialPriorShipmentCreatesOnlyRemainingQuantityWithIndependentReference(){long id=stoppedExchange(1);Map<String,Object> input=continueInput(id);assertEquals(1,number(input,"quantity"));continuation.submit("VERIFY",id,input,"test");approveContinue(id,2);continuation.guardExecution("VERIFY",id);ExchangeFulfillment f=fulfillment();assertTrue(f.reserve("VERIFY",id));f.materialize("VERIFY",id);Map<String,Object> e=service.row("VERIFY",id,false),replacement=db.query("SELECT * FROM oms_order_line WHERE id=?",ROW,e.get("fulfillment_line_id")).get(0);assertEquals(1,number(replacement,"quantity"));assertEquals("EXCHANGE:"+id+":2",replacement.get("stock_reference"));assertEquals(2,number(replacement,"fulfillment_round"));assertEquals(1,db.queryForObject("SELECT cancelled_quantity FROM oms_order_line WHERE exchange_id=? AND fulfillment_round=1",Integer.class,id));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM oms_order",Integer.class));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM oms_exchange",Integer.class));assertEquals("THX_TEST",e.get("return_sn"));assertEquals("PASSED",e.get("return_qc"));verify(continuationReturns,never()).prepare(anyString(),anyLong(),anyMap(),anyString());}
    @Test void continueCannotIncreaseOrShrinkRemainingQuantity(){long id=stoppedExchange(1);Map<String,Object> input=continueInput(id);input.put("quantity",2);assertThrows(IllegalArgumentException.class,()->continuation.submit("VERIFY",id,input,"test"));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM oms_exchange_round",Integer.class));}
    @Test void liveOldDemandOrUncertainCutoffBlocksContinuation(){long id=stoppedExchange(0);db.update("UPDATE oms_order_line SET cancelled_quantity=0 WHERE exchange_id=?",id);assertThrows(IllegalArgumentException.class,()->continuation.preview("VERIFY",id));db.update("UPDATE oms_order_line SET cancelled_quantity=quantity WHERE exchange_id=?",id);db.update("INSERT INTO oms_exchange_control(company_code,exchange_id,kind,mode,reason,actor,state,request_version) VALUES ('VERIFY',?,'OUTBOUND','TERMINATE','test','test','REVIEW',1)",id);assertThrows(IllegalArgumentException.class,()->continuation.preview("VERIFY",id));}
    @Test void continuationRejectsPendingReceiptReviewAndUnpostedReceipt(){long id=stoppedExchange(0);when(continuationWms.reviewSummaries(anyString(),anyList(),anyString())).thenReturn(R.ok(Collections.singletonList(map("pending_count",1))));assertThrows(IllegalArgumentException.class,()->continuation.preview("VERIFY",id));when(continuationWms.reviewSummaries(anyString(),anyList(),anyString())).thenReturn(R.ok(Collections.emptyList()));when(continuationWms.receipts(anyString(),anyString(),anyBoolean(),anyString())).thenReturn(R.ok(Collections.singletonList(map("id",1))));assertThrows(IllegalArgumentException.class,()->continuation.preview("VERIFY",id));}
    @Test void newRefundAfterSubmissionPreventsApprovalButStillAllowsRejection(){long id=stoppedExchange(0);continuation.submit("VERIFY",id,continueInput(id),"test");db.update("UPDATE oms_platform_order SET change_pending=1,update_categories='REFUND' WHERE id=?",platform);assertThrows(IllegalArgumentException.class,()->approveContinue(id,2));assertEquals("REVIEW",db.queryForObject("SELECT state FROM oms_exchange_round WHERE exchange_id=? AND round_no=2",String.class,id));Map<String,Object> input=controlInput(id);input.putAll(map("decision","REJECT","reason","refund conflict"));continuation.review("VERIFY",id,2,input,"test");assertEquals("REJECTED",db.queryForObject("SELECT state FROM oms_exchange_round WHERE exchange_id=? AND round_no=2",String.class,id));}
    @Test void continuationIsVersionedAndCompanyScoped(){long id=stoppedExchange(0);Map<String,Object> input=continueInput(id);assertThrows(IllegalArgumentException.class,()->continuation.submit("OTHER",id,input,"test"));db.update("UPDATE oms_exchange SET control_version=control_version+1 WHERE id=?",id);assertThrows(IllegalArgumentException.class,()->continuation.submit("VERIFY",id,input,"test"));}
    @Test void lateEarlierShipmentInvalidatesApprovedRoundBeforeReservation(){long id=stoppedExchange(0);continuation.submit("VERIFY",id,continueInput(id),"test");approveContinue(id,2);db.update("UPDATE oms_order_shipment_line l JOIN oms_order_shipment s ON s.id=l.shipment_id SET l.shipped_quantity=1 WHERE s.exchange_id=?",id);assertThrows(IllegalArgumentException.class,()->continuation.guardExecution("VERIFY",id));verify(continuationStock,never()).execute(anyString(),anyString(),any(),anyString());}
    @Test void oldRoundCannotDispatchAfterNewRoundApproval(){long id=stoppedExchange(0);Map<String,Object> old=db.query("SELECT * FROM oms_order_shipment WHERE exchange_id=?",ROW,id).get(0);continuation.submit("VERIFY",id,continueInput(id),"test");approveContinue(id,2);assertThrows(IllegalArgumentException.class,()->ExchangeRounds.guardShipment(service.row("VERIFY",id,false),old));}
